.tooltip:after {
  position: absolute;
  width: 0;
  height: 0;
  border: 4px solid transparent;
  content: '';
}
.tooltip-top {
  bottom: calc(100% + 10px);
}
.tooltip-top,
.tooltip-top:after {
  left: 50%;
  transform: translate3d(-50%, 0, 0);
}
.tooltip-top:after {
  top: 100%;
  border-top-color: #ffffff;
}
.tooltip-bottom {
  top: calc(100% + 10px);
}
.tooltip-bottom,
.tooltip-bottom:after {
  left: 50%;
  transform: translate3d(-50%, 0, 0);
}
.tooltip-bottom:after {
  bottom: 100%;
  border-bottom-color: #ffffff;
}
.tooltip-left {
  right: calc(100% + 10px);
}
.tooltip-left,
.tooltip-left:after {
  top: 50%;
  transform: translate3d(0, -50%, 0);
}
.tooltip-left:after {
  left: 100%;
  border-left-color: #ffffff;
}
.tooltip-right {
  left: calc(100% + 10px);
}
.tooltip-right,
.tooltip-right:after {
  top: 50%;
  transform: translate3d(0, -50%, 0);
}
.tooltip-right:after {
  right: 100%;
  border-right-color: #ffffff;
}
.notification {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 3;
  font-size: 18px;
  background-color: rgba(15, 15, 15, 0.7);
  color: #ffffff;
  animation: fade-in 250ms linear both;
}
.container {
  font-family: Lato, "Helvetica Neue", Helvetica, Arial, sans-serif;
}
.title {
  font-weight: 900;
}
.buttons {
  margin: -6px;
}
.buttons .button {
  margin: 6px;
}
.button.normal,
.button.normal.icon {
  font-weight: normal;
}
.button.normal:hover,
.button.normal.icon:hover,
.button.normal:focus,
.button.normal.icon:focus {
  border-color: #ffffff;
}
.button.secondary,
.button.secondary.icon {
  padding-left: 0;
  padding-right: 0;
  color: rgba(255, 255, 255, 0.3);
  background-color: transparent;
  font-weight: normal;
}
.button.secondary:hover,
.button.secondary.icon:hover,
.button.secondary:focus,
.button.secondary.icon:focus {
  color: rgba(255, 255, 255, 0.7);
  background-color: transparent;
}
.input-text,
.input-textarea {
  background-color: rgba(255, 255, 255, 0.15);
}
.input-text:hover,
.input-textarea:hover,
.input-text:focus,
.input-textarea:focus {
  border-color: #ffffff;
}
.input-select select {
  padding-top: 11px;
  padding-bottom: 11px;
  border: solid 1px transparent;
  border-radius: 4px;
}
.input-select select:hover,
.input-select select:focus {
  border-color: #ffffff;
}
.input-check label {
  padding: 11px 16px;
  background-color: rgba(255, 255, 255, 0.15);
  border: solid 1px transparent;
  border-radius: 4px;
}
.input-check label input[type='radio'] + span:before,
.input-check label input[type='checkbox'] + span:before {
  background-color: rgba(255, 255, 255, 0.2);
}
.input-check label:hover,
.input-check label:focus {
  border-color: #ffffff;
}
.note {
  color: rgba(255, 255, 255, 0.3);
}
@keyframes shake {
  100% {
    transform: none;
  }
  0%,
  99% {
    transform: translate(0, 0);
  }
  20% {
    transform: translateX(-10px);
  }
  60% {
    transform: translateX(-5px);
  }
  40% {
    transform: translateX(10px);
  }
  80% {
    transform: translateX(5px);
  }
}
.form.submit .invalid {
  animation: shake 600ms;
}
@keyframes sent-backdrop {
  0%,
  100% {
    opacity: 0;
    background-color: rgba(15, 15, 15, 0);
  }
  50%,
  75% {
    opacity: 0.6;
    background-color: #0f0f0f;
  }
}
@keyframes success-icon-scale {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.8);
  }
  50% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
  75% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.2);
  }
}
@keyframes success-icon-show-path {
  0% {
    opacity: 0;
  }
  50% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
@keyframes success-icon-draw-circle {
  0% {
    opacity: 1;
    stroke-dashoffset: 150.72;
  }
  25% {
    opacity: 1;
    stroke-dashoffset: 75.36;
  }
  50% {
    opacity: 1;
    stroke-dashoffset: 0;
  }
  100% {
    opacity: 0;
    stroke-dashoffset: 0;
  }
}
@keyframes success-icon-draw-check {
  0% {
    opacity: 1;
    stroke-dashoffset: 36;
  }
  25% {
    opacity: 1;
    stroke-dashoffset: 18;
  }
  50% {
    opacity: 1;
    stroke-dashoffset: 0;
  }
  100% {
    opacity: 0;
    stroke-dashoffset: 0;
  }
}
.root.form-sending .content:before {
  content: '';
  display: block;
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  animation: sent-backdrop 2s both;
}
.root.form-sending .content .success-icon {
  display: block;
  width: 100%;
  height: 100%;
  animation: success-icon-scale 1.8s linear both;
}
.root.form-sending .content .success-icon path {
  animation: success-icon-show-path 1.2s linear both;
}
.root.form-sending .content .success-icon circle {
  animation: success-icon-draw-circle 1.2s linear both;
}
.root.form-sending .content .success-icon polyline {
  animation: success-icon-draw-check 1.2s linear both;
}

